// Normalize NewsAPI articles into a common shape for merging
const articles = $input.first().json.articles || [];

return articles.map(article => ({
  json: {
    source: "news",
    title: article.title,
    description: article.description || "",
    url: article.url,
    publishedAt: article.publishedAt
  }
}));

const items = $input.first().json.rss.channel.item || [];

return items.map(item => ({
  json: {
    source: "trends",
    title: item.title,
    description: item['ht:news_item']?.['ht:news_item_snippet'] || "",
    url: item['ht:news_item']?.['ht:news_item_url'] || item.link || "",
    publishedAt: item.pubDate
  }
}));

// Trim payload to reduce token usage
const MAX_ITEMS = 15;        // cap item count — top N is plenty for ranking
const MAX_DESC_LENGTH = 100; // characters, not tokens — keeps things simple

const items = $input.all();

const trimmed = items.slice(0, MAX_ITEMS).map(item => {
  const j = item.json;
  return {
    source: j.source,
    title: j.title,
    description: (j.description || "").slice(0, MAX_DESC_LENGTH)
  };
});

return [{ json: { items: trimmed } }];
